import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../services/api.service';

interface NotificationRecord {
  id: number;
  title: string;
  message: string;
  type: string;
  targetType: string;
  targetId?: number;
  actionUrl?: string;
  broadcast: boolean;
  createdAt: string;
}

@Component({
  selector: 'app-notifications-admin',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;">
      <h1 style="font-size:24px;font-weight:700;">🔔 Notifications</h1>
      <button class="btn btn-primary" (click)="showForm = !showForm">{{ showForm ? 'Cancel' : '+ Send Notification' }}</button>
    </div>

    <!-- Send Form -->
    <div class="card" *ngIf="showForm" style="margin-bottom:20px;">
      <h3 style="margin-bottom:16px;">Send New Notification</h3>
      <div style="display:grid;gap:16px;">
        <input [(ngModel)]="formData.title" placeholder="Title" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
        <textarea [(ngModel)]="formData.message" placeholder="Message" rows="3" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;"></textarea>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
          <select [(ngModel)]="formData.type" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
            <option value="info">Info</option>
            <option value="success">Success</option>
            <option value="warning">Warning</option>
            <option value="error">Error</option>
          </select>
          <select [(ngModel)]="formData.targetType" (change)="onTargetTypeChange()" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
            <option value="ALL">All Students</option>
            <option value="USER">Specific Users</option>
            <option value="COURSE">Specific Course</option>
            <option value="BATCH">Specific Batch</option>
          </select>
        </div>
        <div *ngIf="formData.targetType === 'USER'" style="display:grid;gap:8px;">
          <input [(ngModel)]="formData.userIds" placeholder="User IDs (comma separated)" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
        </div>
        <div *ngIf="formData.targetType === 'COURSE' || formData.targetType === 'BATCH'" style="display:grid;gap:8px;">
          <input type="number" [(ngModel)]="formData.targetId" placeholder="Target ID (course/batch)" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
        </div>
        <input [(ngModel)]="formData.actionUrl" placeholder="Action URL (route for mobile app, e.g. /courses)" style="width:100%;padding:10px;border:1px solid #E2E8F0;border-radius:8px;">
      </div>
      <div style="margin-top:16px;display:flex;gap:12px;">
        <button class="btn btn-primary" (click)="send()" [disabled]="sending">Send Notifications</button>
        <button class="btn" style="background:#E2E8F0;" (click)="resetForm()">Reset</button>
      </div>
      <div *ngIf="sendError" style="margin-top:8px;color:#EF4444;font-size:14px;">{{ sendError }}</div>
    </div>

    <!-- Notifications Table -->
    <div class="card" *ngIf="!showForm">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
        <h3 style="font-weight:700;">Sent Notifications ({{ notifications.length }})</h3>
        <button class="btn" style="background:#EEF2FF;color:#4338CA;padding:6px 14px;font-size:12px;" (click)="loadNotifications()">Refresh</button>
      </div>
      <table *ngIf="notifications.length">
        <thead>
          <tr><th>Title</th><th>Message</th><th>Type</th><th>Target</th><th>Date</th><th>Actions</th></tr>
        </thead>
        <tbody>
          <tr *ngFor="let n of notifications">
            <td style="font-weight:600;">{{ n.title }}</td>
            <td style="max-width:300px;">{{ n.message }}</td>
            <td>
              <span [class.badge-success]="n.type === 'success'" [class.badge-warning]="n.type === 'warning'" [class.badge-danger]="n.type === 'error'" class="badge">{{ n.type }}</span>
            </td>
            <td>{{ n.targetType }}{{ n.targetId ? (' / ' + n.targetId) : '' }}</td>
            <td style="font-size:13px;color:#64748B;">{{ n.createdAt | date:'short' }}</td>
            <td>
              <button class="btn" style="background:#FEE2E2;color:#991B1B;padding:4px 12px;font-size:12px;" (click)="delete(n)">Delete</button>
            </td>
          </tr>
        </tbody>
      </table>
      <div *ngIf="!loading && notifications.length === 0" style="color:#64748B;padding:20px;text-align:center;">No notifications found.</div>
      <div *ngIf="loading" style="color:#64748B;padding:20px;text-align:center;">Loading...</div>
    </div>
  `
})
export class NotificationsAdminComponent implements OnInit {
  private api = inject(ApiService);

  showForm = false;
  loading = false;
  sending = false;
  sendError = '';
  notifications: NotificationRecord[] = [];

  formData = {
    title: '',
    message: '',
    type: 'info',
    targetType: 'ALL',
    targetId: null as number | null,
    userIds: '',
    actionUrl: ''
  };

  ngOnInit() {
    this.loadNotifications();
  }

  onTargetTypeChange() {
    this.formData.targetId = null;
    this.formData.userIds = '';
  }

  loadNotifications() {
    this.loading = true;
    this.api.get<any[]>('notifications/broadcasts').subscribe({
      next: (data: any[]) => {
        // The backend returns Notification entities. Filter broadcasts (sent by admin).
        this.notifications = data
          .filter(n => n.broadcast === true || n.broadcast === 1)
          .map(n => ({
            id: n.id,
            title: n.title,
            message: n.message,
            type: n.type,
            targetType: n.targetType,
            targetId: n.targetId,
            actionUrl: n.actionUrl,
            broadcast: n.broadcast,
            createdAt: n.createdAt
          }));
        this.loading = false;
      },
      error: () => { this.loading = false; }
    });
  }

  send() {
    if (!this.formData.title) return;
    this.sending = true;
    this.sendError = '';

    const userIdsArray = this.formData.targetType === 'USER' && this.formData.userIds
      ? this.formData.userIds.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n))
      : null;

    const payload = {
      title: this.formData.title,
      message: this.formData.message,
      type: this.formData.type,
      targetType: this.formData.targetType,
      targetId: this.formData.targetId,
      userIds: userIdsArray,
      actionUrl: this.formData.actionUrl,
      broadcast: true
    };

    this.api.post<any[]>('notifications', payload).subscribe({
      next: () => {
        this.sending = false;
        this.showForm = false;
        this.loadNotifications();
      },
      error: (err) => {
        this.sending = false;
        this.sendError = err.error?.message || 'Failed to send notification';
      }
    });
  }

  delete(n: NotificationRecord) {
    if (confirm('Delete this notification?')) {
      this.api.delete<void>(`notifications/${n.id}`).subscribe({
        next: () => this.loadNotifications(),
        error: () => {}
      });
    }
  }

  resetForm() {
    this.formData = {
      title: '', message: '', type: 'info', targetType: 'ALL',
      targetId: null, userIds: '', actionUrl: ''
    };
    this.showForm = false;
    this.sendError = '';
  }
}
